# Code generated by Claude
"""
Measurement only (no motion is changed): the left arm's joints through the whole moved-layout demo episode.

    python experiments/left_arm_motion_measure.py RECORDING_DIR OUT_DIR [--episode-log LOG]

Replays the recording (src/replay.py, states verified bit-identical) and records at every physics step (750 Hz) the left arm's seven joints: the commanded position (the ctrl
of the position actuators, i.e. what the replay reads), the actual position and the actual velocity. Acceleration and jerk are finite differences of the velocity at the physics
step (750 Hz) and at the control tick (150 Hz). The phase of every tick comes from the recording's labels ("<k>/<N> <TYPE>: <phase> [status]"; a phase is the text before " [").
Writes OUT_DIR/left_arm.npz (the raw series), OUT_DIR/phases.json (the phase intervals) and OUT_DIR/summary.json; plots are made by experiments/left_arm_motion_report.py.
"""

import argparse
import json
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
os.environ.setdefault("MUJOCO_GL", "egl")

import numpy as np  # noqa: E402

import src.replay as replay_mod  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402


def main(args):
    rec_dir, out = Path(args.recording), Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    meta = json.loads((rec_dir / "meta.json").read_text())
    ids, series = {}, {"t": [], "cmd": [], "q": [], "qd": []}

    def hook(step_count, data):
        if not ids:
            ids.update(arm_ids(MODEL[0], "left"))
        series["t"].append(data.time)
        series["cmd"].append(data.ctrl[ids["act"]].copy())
        series["q"].append(data.qpos[ids["qadr"]].copy())
        series["qd"].append(data.qvel[ids["vadr"]].copy())

    MODEL = [None]
    orig = replay_mod.run_loop

    def spy(model, data, sources, cfg, viewer=None):           # only to learn the model (the hook reads ids from it); nothing is changed
        MODEL[0] = model
        return orig(model, data, sources, cfg, viewer=viewer)

    replay_mod.run_loop = spy
    r = replay_mod.replay_run(rec_dir, out_dir=out, video="none", verify=True, quiet=True, step_hook=hook)
    replay_mod.run_loop = orig
    print(f"replay ok {r['ok']} ticks {r['ticks']} mismatch {r['mismatch']}", flush=True)
    t, cmd, q, qd = (np.array(series[k]) for k in ("t", "cmd", "q", "qd"))
    spt = int(round(len(t) / r["ticks"]))
    labels = meta["labels"]
    tick_t = t[spt - 1::spt]                                    # time at the end of each tick
    phases = []                                                 # [start_tick, end_tick, key] of the text before " [" ; one entry per run of equal keys
    for i, l in enumerate(labels):
        key = l["label"].split(" [")[0].split("  (+")[0]
        end = labels[i + 1]["tick"] if i + 1 < len(labels) else r["ticks"]
        if phases and phases[-1][2] == key and phases[-1][1] == l["tick"]:
            phases[-1][1] = end
        else:
            phases.append([l["tick"], end, key])
    np.savez_compressed(out / "left_arm.npz", t=t, cmd=cmd, q=q, qd=qd, steps_per_tick=spt, tick_t=tick_t)
    (out / "phases.json").write_text(json.dumps([{"tick": a, "end_tick": b, "t_start": float(t[a * spt]) if a * spt < len(t) else None, "key": k} for a, b, k in phases], indent=1))
    (out / "summary.json").write_text(json.dumps({"replay_ok": bool(r["ok"]), "ticks": r["ticks"], "steps": len(t), "steps_per_tick": spt, "n_phases": len(phases)}, indent=1))
    print(f"saved {len(t)} steps, {len(phases)} phase runs to {out}", flush=True)
    return 0 if r["ok"] else 1


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[1])
    ap.add_argument("recording")
    ap.add_argument("out")
    sys.exit(main(ap.parse_args()))
